// Lints the string literals and JSX text of every screen (src/app, src/components), not only the i18n catalogues
// (PRD §6.6 rule 3, FR-CON-07). Every screen, staff included: no clinical-judgement words generated by the system.
// Patient surfaces (portal, share viewer): no diagnosis words either. Comments, imports and type literals are not text.
// A legitimate use goes in ALLOW with the reason; an entry that no longer matches anything fails, so the list stays honest.
import { readdirSync, readFileSync, statSync } from 'node:fs'
import { join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'
import ts from 'typescript'
import { describe, expect, it } from 'vitest'
import { lintText, type Ruleset } from '.'

const ROOT = fileURLToPath(new URL('../../..', import.meta.url))
const PATIENT_SURFACES = ['src/app/(patient)/', 'src/components/portal/', 'src/app/s/', 'src/components/shares/']

const ALLOW: { file: string; term: string; why: string }[] = [
  { file: 'src/app/page.tsx', term: 'recommend*', why: 'the intended-use statement and the footer say the product does NOT recommend' },
  { file: 'src/app/page.tsx', term: 'risk', why: 'the intended-use statement: it does not "risk-score"' },
  { file: 'src/app/(staff)/patients/[id]/documents/[docId]/page.tsx', term: 'urgency', why: 'staff-only evidence-gate log: names the advice or urgency wording a model value was rejected for' },
  { file: 'src/components/documents/labels.ts', term: 'risk', why: 'staff-only evidence-gate reason: a model asked for a judgement (stage, risk, …), which is never recorded' },
  { file: 'src/app/(patient)/layout.tsx', term: 'onco*', why: 'the tab title says OncoSetu only for a signed-in patient whose disclosure is cleared' },
  { file: 'src/components/shares/CreateShareForm.tsx', term: 'onco*', why: 'compares the payload brand; never rendered' },
  { file: 'src/components/shares/crypto.ts', term: 'onco*', why: 'the encryption context label, never shown' },
]

function files(dir: string, out: string[] = []): string[] {
  for (const f of readdirSync(dir)) {
    const p = join(dir, f)
    if (statSync(p).isDirectory()) files(p, out)
    else if (/\.tsx?$/.test(f) && !/\.test\.tsx?$/.test(f)) out.push(p)
  }
  return out
}

/** Every piece of text a file can put on screen: string and template literals (not imports or types), and JSX text. */
function texts(path: string, source = readFileSync(path, 'utf8')): { line: number; text: string }[] {
  const sf = ts.createSourceFile(path, source, ts.ScriptTarget.Latest, true, path.endsWith('x') ? ts.ScriptKind.TSX : ts.ScriptKind.TS)
  const out: { line: number; text: string }[] = []
  const visit = (n: ts.Node) => {
    let text: string | null = null
    if (ts.isStringLiteral(n) || ts.isNoSubstitutionTemplateLiteral(n)) {
      const p = n.parent
      if (!ts.isImportDeclaration(p) && !ts.isExportDeclaration(p) && !ts.isLiteralTypeNode(p) && !ts.isExternalModuleReference(p)) text = n.text
    } else if (ts.isTemplateHead(n) || ts.isTemplateMiddle(n) || ts.isTemplateTail(n) || ts.isJsxText(n)) text = n.text
    if (text?.trim()) out.push({ line: sf.getLineAndCharacterOfPosition(n.getStart()).line + 1, text })
    ts.forEachChild(n, visit)
  }
  visit(sf)
  return out
}

describe('copy lint: screens (src/app, src/components)', () => {
  it('no clinical-judgement words anywhere; no diagnosis words on patient surfaces', () => {
    const all = [...files(join(ROOT, 'src/app')), ...files(join(ROOT, 'src/components'))].map((p) => relative(ROOT, p))
    expect(all.length).toBeGreaterThan(100) // the walk actually found the screens
    const used = new Set<number>()
    const failures: string[] = []
    let n = 0
    for (const file of all) {
      const rules: Ruleset[] = PATIENT_SURFACES.some((p) => file.startsWith(p)) ? ['judgement', 'diagnosis'] : ['judgement']
      for (const { line, text } of texts(join(ROOT, file))) {
        n++
        for (const h of lintText(text, rules)) {
          const a = ALLOW.findIndex((x) => x.file === file && x.term === h.term)
          if (a >= 0) used.add(a)
          else failures.push(`${file}:${line}: "${h.match}" (${h.ruleset}:${h.term})`)
        }
      }
    }
    expect(n).toBeGreaterThan(1000)
    expect(failures).toEqual([])
    expect(ALLOW.filter((_, i) => !used.has(i)).map((x) => `${x.file} ${x.term}: allowed but no longer used`)).toEqual([])
  })

  it('catches a judgement word in JSX text and a template literal, and ignores comments and imports', () => {
    const src = `import x from 'urgent-lib'\n// worse in a comment\nexport const A = () => <p>Result is abnormal</p>\nexport const b = (n: number) => \`\${n} items urgently\`\n`
    expect(texts('fixture.tsx', src).flatMap((t) => lintText(t.text, ['judgement']).map((h) => h.match))).toEqual(['abnormal', 'urgently'])
  })
})
